/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set(['home']);
  const queue = ['home'];
  const allServers = [];

  // BFS to find all reachable servers
  while (queue.length > 0) {
    const server = queue.shift();
    const neighbors = ns.scan(server);
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
        allServers.push(neighbor);
      }
    }
  }

  // Find hackable servers (low hacking requirement)
  const hackable = [];
  for (const server of allServers) {
    const level = ns.getServerRequiredHackingLevel(server);
    const money = ns.getServerMoneyAvailable(server);
    if (level <= 1 && money > 0) {
      hackable.push({ name: server, money });
    }
  }

  // Sort by money descending
  hackable.sort((a, b) => b.money - a.money);

  if (hackable.length === 0) {
    ns.tprint('No hackable servers found at level 1.');
    return;
  }

  const target = hackable[0].name;
  ns.tprint(`Target: ${target} with $${hackable[0].money}`);

  // Nuke and hack loop
  ns.nuke(target);
  ns.tprint(`Nuked ${target}`);

  while (true) {
    const result = await ns.hack(target);
    ns.tprint(`Hacked ${target}, gained: $${result}`);
    await ns.sleep(100);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const servers = ns.scan();
  let targets = [];
  for (let s of servers) {
    let lvl = ns.getServerRequiredHackingLevel(s);
    let money = ns.getServerMoneyAvailable(s);
    if (lvl <= ns.getHackingLevel() && money > 0) {
      targets.push({name: s, money: money});
    }
  }
  if (targets.length === 0) {
    ns.print('No hackable targets found');
    return;
  }
  targets.sort((a, b) => b.money - a.money);
  let target = targets[0].name;
  ns.print('Hacking target: ' + target);
  while (true) {
    await ns.hack(target);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const neighbors = ns.scan('home');
  let target = null;
  let myLevel = ns.getHackingLevel();

  for (const server of neighbors) {
    if (ns.getServerMoneyAvailable(server) > 0) {
      let reqLevel = ns.getServerRequiredHackingLevel(server);
      if (reqLevel <= myLevel) {
        target = server;
        break;
      }
    }
  }

  if (!target) {
    ns.tprint('No hackable target found');
    return;
  }

  if (!ns.hasRootAccess(target)) {
    ns.nuke(target);
  }

  while (true) {
    await ns.hack(target);
  }
}

